// Dutch deck regeneration script
// 35 nodes x 112 cards = 3920 total cards
// Format: [target, english, grammar|null, tags]
// tags: g=general, t=travel, w=work, f=family

function t(tags) {
  const map = { g: 'general', t: 'travel', w: 'work', f: 'family' };
  return tags.split('').map(c => map[c]);
}

